actionCenter.usePublicMethod:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, openConfirmBox, parseJson } = globalUtils
  // 将表头数据转为form表单结构
  function transformAtoB(a, labval = { lab: "title", val: "value", name: "key"}, excludeKeys = ["operate"]) {
      if(isEmpty(a)) return a
      return a
          .filter(item => !excludeKeys.includes(item.key)) // 过滤掉 excludeKeys 中的项
          .map(item => {
              // 基础映射
              const transformedItem = {
                  name: item[labval.name],       // key -> name
                  label: item[labval.lab],    // title -> label
                  type: item.type || "input", // 如果没有 type，默认是 input
                  value: item[labval.val] !== undefined ? item[labval.val] : getDefaultValue(item.type), // 根据 type 设置默认值
              };
              // 保留其他属性（如 disabled、slot、width 等）
              for (const key in item) {
                  if (!["key", "title", "type", "value"].includes(key)) {
                      transformedItem[key] = item[key];
                  }
              }
              return transformedItem;
          });
  }
  // 根据 type 设置默认值
  function getDefaultValue(type) {
      switch (type) {
          case "checkbox":
              return false; // checkbox 默认值为 false
          case "select":
              return null; // select 默认值为 null
          default:
              return ""; // 其他类型默认值为空字符串
      }
  }
  /**
   * 将结构提取为 { name: value } 的形式
   * @param {Array} data - 原始数据结构
   * @returns {Object} - 提取后的 { name: value } 对象
   */
  function extractNameValue(data) {
      return data.reduce((result, item) => {
           if(item.type === "select"){
              const idVal =  item.options?.find(itemVal => itemVal.label === item.value )
              if(idVal){
                result[item.name] = idVal.value
              }else{
                result[item.name] = item.value
              }
          }else{
             result[item.name] = item.value; // 将 name 作为键，value 作为值
          }
          return result;
      }, {});
  }
  // 1. 全连接方式生成边数据
  function generateFullEdges(nodes) {
      const edges = [];
      const n = nodes.length;
      for (let i = 0; i < n; i++) {
          for (let j = i + 1; j < n; j++) {
              edges.push({
                  source: nodes[i].id,
                  target: nodes[j].id,
                  data: {
                      label: `边 ${nodes[i].data.label} - ${nodes[j].data.label}`
                  }
              });
          }
      }
      return edges;
  }
  // 表格数组转换为值
  function transformToValueArray(columns, dataSource, formatter, filterKeys = []) {
    console.log("transformToValueArray", filterKeys)
    const keys = columns.filter(item =>!filterKeys.includes(item.key)).map(col => col.key);
    console.log("keys", keys)
    return dataSource.map(item => 
      keys.map(key => formatter(item[key], key))
    );
  }
  // 数组转置
  function transposeMatrix(matrix) {
      // 检查输入是否为空或不是数组
      if (!Array.isArray(matrix) || matrix.length === 0) {
          return [];
      }
      // 检查是否为二维数组
      if (!Array.isArray(matrix[0])) {
          throw new Error("输入必须是一个二维数组");
      }
      // 使用 map 实现转置
      return matrix[0].map((_, colIndex) => 
          matrix.map(row => row[colIndex])
      );
  }
  // 转换为tree结构
  function processFlightData(flightData, fields) {
      // 验证输入字段是否有效
      if (!Array.isArray(fields) || fields.length === 0) {
          throw new Error("fields must be a non-empty array");
      }
      const labelList = [];
      const planMap = {};
      flightData?.forEach(flight => {
          // 拼接标签键值（用 -- 连接指定字段的值）
          const keyParts = fields.map(field => {
              if (!(field in flight)) {
                  throw new Error(`Field '${field}' does not exist in flight data`);
              }
              return field === 'totalCostPerAir' 
                  ? flight[field].toFixed(2)  // 费用字段保留两位小数
                  : flight[field];
          });
          const labelKey = keyParts.join('--');
          // 添加到标签数组
          labelList.push({ label: labelKey });
          // 添加到映射对象（确保每个航班只存储一次）
          if (!planMap[labelKey]) {
              planMap[labelKey] = flight.allPlan;
          } else {
              console.warn(`Duplicate key detected: ${labelKey}. Using first occurrence.`);
          }
      });
      return { labelList, planMap };
  }
  // 去除交集
  function removeIntersection(arrA, arrB, key = 'label') {
      const keysB = new Set(arrB.map(item => item[key]));
      const keysA = new Set(arrA.map(item => item[key]));
      return {
        uniqueA: arrA.filter(item => !keysB.has(item[key])),
        uniqueB: arrB.filter(item => !keysA.has(item[key]))
      }
  }
  return {
    removeIntersection,
    transposeMatrix,
    transformAtoB,
    extractNameValue,
    generateFullEdges,
    transformToValueArray,
    processFlightData
  }
}

actionCenter.handleOperate:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { openConfirmBox } = globalUtils
  const Params = eventParams.params
  console.log('仿真进度界面操作', Params)
  const tabRow = Params.row
  const activateText = Params?.activateText
  switch (activateText) {
      case 'airfreighter':
