actionCenter.useWinCenter:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, createUuid, deepCopy } = globalUtils
  // 窗口列表数据设置
  const setWinList = ({ type, uuidStr, attribute, curAttribute, data }) => {
    const operations = {
      clear: () => {
        dataCenter[attribute] = [];
        dataCenter[curAttribute] = {};
      },
      add: () => {
        if (isEmpty(data)) return;
        dataCenter[attribute].push(data);
      },
      cover: () => {
        if (isEmpty(data)) return;
        dataCenter[attribute] = data;
      },
      delete: () => {
        if (isEmpty(uuidStr)) return;
        const newList = dataCenter[attribute].filter(
          (item) => item.uuid !== uuidStr
        );
        if (isEmpty(newList)) {
          dataCenter[attribute] = [];
          dataCenter[curAttribute] = {};
          return;
        }
        dataCenter[attribute] = [...newList];
      },
      default: () => {
        if (isEmpty(uuidStr) && isEmpty(data)) return;
        const newList = dataCenter[attribute]?.map((item) =>
          item?.uuid === uuidStr ? { ...item, ...data } : item
        );
        dataCenter[attribute] = [...newList];
        if(!isEmpty(curAttribute)){
          dataCenter[curAttribute] = {...dataCenter[curAttribute], ...data}
        }
      },
    };
    const operation = operations[type] || operations.default;
    operation();
  };
  return {
    setWinList,
  }
}

actionCenter.addWin:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, createUuid, nameRepeat } = globalUtils
  const win = actionCenter.useWinCenter()
  console.log("addWin", eventParams)
  let Params = eventParams.params
  // 新增窗口方法
  const addNewWin = (type, addName, titleName = "子窗口", propValue = {})=>{
    let name = nameRepeat(titleName, dataCenter[addName], "")
    let uuid = createUuid()
    if(type === "plot"){
      propValue = { dataSource: [], domId: `Plot${uuid}`}
    }
    let NewWin = {
      uuid: uuid,
      name: name,
      isMaximized: false,
      isMinimized: false,
      contentType: type,
      style: {
        width: 440,
        height: 450,
        left: 0,
        top: 0,
        rotate: 0,
        pointerEvents: "all",
      },
      lastStyle: {},
      propValue: propValue,
    }
    win.setWinList({ type: "add", attribute: addName, data: NewWin})
  }
  if(Params.activateText === "addPlot"){
    addNewWin("plot","plotWinList")
    return
  }
  if(Params[0].activateText === "addTableData"){
    let propValue = {
      showBorder: true,
      activeClickRow: true,
      noDataHints: true,
      textAlign: 'center',
      columns: Params[0].columns,
      dataSource: Params[0].dataSource
    }
    addNewWin("table", "tableWinList", Params[0].name, propValue)
  }
}

